package control

import (
	controlconnect "github.com/vrooli/vrooli/packages/proto/gen/go/lighting-control/v1/control/controlconnect"
	"lighting-control/internal/module"
)

var Endpoints = []module.EndpointDescriptor{
	{ID: "control_backend_status", Path: controlconnect.ControlServiceGetBackendStatusProcedure, Method: "POST", Summary: "Get OpenRGB backend status", Description: "Reports whether the explicitly configured loopback SDK backend is ready and its protocol compatibility.", Category: "control", Response: &module.Schema{Type: "object", Properties: map[string]string{"backend": "BackendStatus"}}},
	{ID: "control_list_controllers", Path: controlconnect.ControlServiceListControllersProcedure, Method: "POST", Summary: "List lighting controllers", Description: "Discovers controllers through OpenRGB SDK protocol v6 and reports stable unique IDs and zone capabilities.", Category: "control", Response: &module.Schema{Type: "object", Properties: map[string]string{"backend": "BackendStatus", "controllers": "array<Controller>"}}},
	{ID: "control_enroll_controller", Path: controlconnect.ControlServiceEnrollControllerProcedure, Method: "POST", Summary: "Enroll or unenroll a controller", Description: "Persists explicit controller enrollment using the SDK v6 unique controller ID.", Category: "control", Response: &module.Schema{Type: "object", Properties: map[string]string{"controller": "Controller"}}},
	{ID: "control_set_zone_state", Path: controlconnect.ControlServiceSetZoneStateProcedure, Method: "POST", Summary: "Set desired state for a lighting zone", Description: "Persists the requested state, then returns a per-zone result that distinguishes a local socket write from observed output.", Category: "control", Response: &module.Schema{Type: "object", Properties: map[string]string{"result": "ZoneApplyResult"}}},
	{ID: "control_set_manual_off", Path: controlconnect.ControlServiceSetManualOffProcedure, Method: "POST", Summary: "Set manual Off override", Description: "Persists a higher-priority manual Off override for all enrolled or explicitly selected controllers, optionally with expiry.", Category: "control", Response: &module.Schema{Type: "object", Properties: map[string]string{"override": "ManualOverride", "results": "array<ZoneApplyResult>"}}},
	{ID: "control_get_desired_state", Path: controlconnect.ControlServiceGetDesiredStateProcedure, Method: "POST", Summary: "Get persisted desired lighting state", Description: "Returns durable per-zone desired state, last command outcome, and the current manual Off override including expiry.", Category: "control", Response: &module.Schema{Type: "object", Properties: map[string]string{"zones": "array<ZoneStatus>", "manual_override": "ManualOverride"}}},
	{ID: "control_clear_manual_override", Path: controlconnect.ControlServiceClearManualOverrideProcedure, Method: "POST", Summary: "Clear manual Off override", Description: "Clears the persisted manual override so configured desired states can resume.", Category: "control", Response: &module.Schema{Type: "object", Properties: map[string]string{"cleared": "boolean"}}},
	{ID: "control_reconcile", Path: controlconnect.ControlServiceReconcileProcedure, Method: "POST", Summary: "Reconcile persisted lighting state", Description: "Refreshes SDK v6 controller identities and attempts each persisted zone command once, preserving per-zone outcomes.", Category: "control", Response: &module.Schema{Type: "object", Properties: map[string]string{"zones": "array<ReconcileZoneResult>", "completed_at": "timestamp"}}},
}
